#!/usr/bin/env bash
# Checks a release APK declares exactly one FileProvider, the camera-capture plugin's
# CaptureFileProvider (authority com.checkflat.app.cameracapture, not exported), that the
# Tauri template's broad com.checkflat.app.fileprovider is absent, and that the provider's paths
# resource declares only cache-path captures/ and reports/ (D-028). src-tauri/gen/android can be
# regenerated by the Tauri CLI, which would bring the broad provider back without anyone noticing;
# this reads the APK itself, so it sees what ships.
#
# Usage: scripts/check-fileprovider.sh <apk> <build-tools dir>   (the dir holds aapt2)
# Fails closed: a missing aapt2, a failed or empty dump, or anything it cannot find is a failure.
set -euo pipefail

PROVIDER_CLASS="com.checkflat.cameracapture.CaptureFileProvider"
AUTHORITY="com.checkflat.app.cameracapture"
FORBIDDEN_AUTHORITY="com.checkflat.app.fileprovider"
EXPECTED_PATHS=$'cache-path|captures/\ncache-path|reports/'

fail() { echo "::error::FileProvider check: $*" >&2; exit 1; }

[ $# -eq 2 ] || fail "usage: $0 <apk> <build-tools dir>"
APK=$1
AAPT2="$2/aapt2"
[ -f "$APK" ] || fail "APK not found: $APK"
[ -x "$AAPT2" ] || fail "aapt2 not found or not executable: $AAPT2"

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

# Dumps to a file and fails on an error or an empty result.
dump() { # <out file> <aapt2 args…>
  local out=$1; shift
  "$AAPT2" dump "$@" > "$out" 2> "$out.err" || fail "aapt2 dump $* failed: $(cat "$out.err")"
  [ -s "$out" ] || fail "aapt2 dump $* printed nothing"
}

dump "$TMP/manifest.txt" xmltree --file AndroidManifest.xml "$APK"
dump "$TMP/resources.txt" resources "$APK"
grep -q "E: application" "$TMP/manifest.txt" || fail "no <application> in the manifest dump"

# One line per <provider>: name|authorities|exported|paths resource id (empty when it has no
# FILE_PROVIDER_PATHS meta-data, i.e. it is not a FileProvider).
awk '
  function indent(s) { match(s, /^ */); return RLENGTH }
  function val(s) {
    sub(/^[^)]*\)=/, "", s)
    if (s ~ /^"/) { sub(/^"/, "", s); sub(/".*$/, "", s) } else { sub(/ .*$/, "", s) }
    return s
  }
  function flush() { if (inprov) print pname "|" pauth "|" pexp "|" pres; inprov = 0 }
  /^ *E: / {
    ind = indent($0)
    if (inprov && ind <= provind) flush()
    if ($0 ~ /E: provider /) { inprov = 1; provind = ind; pname = ""; pauth = ""; pexp = "unset"; pres = ""; elem = "provider"; next }
    if (inprov) { elem = ($0 ~ /E: meta-data /) ? "meta" : "other"; mname = ""; mres = "" }
    next
  }
  inprov && /^ *A: / {
    if (elem == "provider") {
      if ($0 ~ /android:name\(/) pname = val($0)
      else if ($0 ~ /android:authorities\(/) pauth = val($0)
      else if ($0 ~ /android:exported\(/) pexp = val($0)
    } else if (elem == "meta") {
      if ($0 ~ /android:name\(/) mname = val($0)
      else if ($0 ~ /android:resource\(/) mres = val($0)
      if (mname == "android.support.FILE_PROVIDER_PATHS" && mres != "") pres = mres
    }
  }
  END { flush() }
' "$TMP/manifest.txt" > "$TMP/providers.txt"
[ -s "$TMP/providers.txt" ] || fail "no <provider> found in the manifest dump"

# The file a resource id points at (release builds shorten resource paths, e.g. res/l7.xml).
resource_file() { # <@0x7f…>
  local id=${1#@}
  awk -v id="$id" '
    $1 == "resource" && $2 == id { want = 1; next }
    want { for (i = 1; i <= NF; i++) if ($i == "(file)") { print $(i + 1); exit } ; exit }
  ' "$TMP/resources.txt"
}

# tag|path per element under <paths>.
paths_of() { # <file in apk> <out>
  dump "$2.xml" xmltree --file "$1" "$APK"
  awk '
    /^ *E: paths/ { inpaths = 1; next }
    inpaths && /^ *E: / { if (tag != "") print tag "|" path; tag = $2; path = ""; next }
    inpaths && /^ *A: path=/ { s = $0; sub(/^ *A: path="/, "", s); sub(/".*$/, "", s); path = s }
    END { if (tag != "") print tag "|" path }
  ' "$2.xml" > "$2"
}

found=0
ok_line=""
report=""
while IFS='|' read -r name auth exported res; do
  [ -n "$res" ] || continue # not a FileProvider (e.g. androidx.startup.InitializationProvider)
  found=$((found + 1))
  file=$(resource_file "$res")
  [ -n "$file" ] || fail "paths resource $res of $name not found in the APK's resource table"
  paths_of "$file" "$TMP/paths-$found.txt"
  [ -s "$TMP/paths-$found.txt" ] || fail "no path elements in $file ($name)"
  declared=$(tr '\n' ' ' < "$TMP/paths-$found.txt")
  report+="  $name authority=$auth exported=$exported paths: $declared"$'\n'
  if [ "$name" = "$PROVIDER_CLASS" ] && [ "$auth" = "$AUTHORITY" ] && [ "$exported" = "false" ] \
     && [ "$(sort "$TMP/paths-$found.txt")" = "$(sort <<< "$EXPECTED_PATHS")" ]; then
    ok_line="$name ($auth, not exported): $(sort "$TMP/paths-$found.txt" | tr '\n' ' ')"
  fi
done < "$TMP/providers.txt"

printf 'FileProviders in %s:\n%s' "$(basename "$APK")" "$report"
if grep -qF "$FORBIDDEN_AUTHORITY" "$TMP/manifest.txt"; then
  fail "the template provider $FORBIDDEN_AUTHORITY is in the manifest"
fi
[ "$found" -eq 1 ] || fail "expected exactly one FileProvider, found $found"
[ -n "$ok_line" ] || fail "the FileProvider is not $PROVIDER_CLASS ($AUTHORITY, exported=false) with only cache-path captures/ and reports/"
echo "FileProvider OK: $ok_line"
